import React, {
    useState,
    useEffect,
    useCallback,
    useRef
} from 'react';

import {
    View,
    FlatList,
} from 'react-native';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';

import { ListItem } from '../../components/ListItem';
import { ListFooter } from '../../components/ListFooter';
import { ListHeader } from '../../components/ListHeader';

import { styles } from './styles';
import api from '../../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
    }]
}

export function RenderList() {
    const { feed, refreshGetList } = useContexState();
    const { LoadPage } = useLoadPage();

    const [refreshing, setRefreshing] = useState(false);
    const [getList, setGetList] = useState<ConvertListReturn>();

    const refContainer = useRef<FlatList>(null);

    useEffect(() => {
        LoadPage();
    }, []);

    function convertList({ data }: ConvertListParam) {
        return data.reduce<any>((h, card) =>
            Object.assign(h, {
                [card.number]: (h[card.number] || [])
                    .concat(
                        {
                            id: card.id,
                            name: card.name,
                            phone: card.phone,
                            price: card.price,
                        })
            }), {}
        );
    };

    useEffect(() => {
        api.get("getCards", { params: { firstNumber: 0, lastNumber: 503 } }
        ).then((responce) => {
            console.log(responce.data);
            setGetList(convertList(responce))});
    }, [refreshGetList]);


    const renderItem = useCallback(
        ({ item }) =>
            <ListItem data={item} list={getList} />,
        [getList]
    );

    const keyExtractor = useCallback(
        (item) => item.id.toString(),
        []
    );

    function scrollToIndex() {
        if (feed[0]?.lineCards !== 0) {
            refContainer.current?.scrollToIndex({
                index: 0,
                animated: false,
            });
        };
    };

    async function refreshList() {
        setRefreshing(true);
        await LoadPage();
        setRefreshing(false);
    };

    console.log('render123');

    return (
        <View style={styles.listContainer}>
            <FlatList
                viewabilityConfig={{
                    viewAreaCoveragePercentThreshold: 10,
                }}
                ref={refContainer}
                initialNumToRender={10}
                key="list"
                data={feed}
                windowSize={80}
                showsVerticalScrollIndicator={false}
                onRefresh={refreshList}
                refreshing={refreshing}
                renderItem={renderItem}
                keyExtractor={keyExtractor}
                updateCellsBatchingPeriod={50}
                ListHeaderComponent={ListHeader}
                ListFooterComponent={() => {
                    scrollToIndex();
                    return ListFooter();
                }}
            />
        </View>
    );
};
